+// CTAMintedKey is the reserved content_data key recording which CTA url THIS
+// resolver minted, per url field. Value-bound on purpose: a boolean would
+// survive a section-editor field update and licence the recompute to clobber
+// the human's new value (bugs_open/248's mechanism), whereas a stale VALUE
+// mismatches and correctly reads as authored.
+const CTAMintedKey = "__cta_minted"
+
+// SetCTAMinted records that `url` was written into `field` by a resolver.
+func SetCTAMinted(resolved map[string]interface{}, field, url string) {
+	if resolved == nil || field == "" || url == "" {
+		return
+	}
+	m, _ := resolved[CTAMintedKey].(map[string]interface{})
+	if m == nil {
+		m = map[string]interface{}{}
+		resolved[CTAMintedKey] = m
+	}
+	m[field] = url
+}
+
+// CTAMintedCovers reports whether the stamp in `contentData` names `url` for
+// `field`. False for an absent stamp, which is what preserves today's
+// behaviour on every unstamped row (no backfill).
+func CTAMintedCovers(contentData map[string]interface{}, field, url string) bool {
+	if contentData == nil || field == "" || url == "" {
+		return false
+	}
+	m, _ := contentData[CTAMintedKey].(map[string]interface{})
+	minted, _ := m[field].(string)
+	return minted != "" && NormalizePagePath(minted) == NormalizePagePath(url)
+}

