+func storedCTADestinationIsAuthored(stored map[string]interface{}, field string,
+	validPages datahelpers.PageURLSet) bool {
+	url, _ := stored[field].(string)
+	if url == "" || !ctaExcludedDestination(url) || !validPages.Contains(url) {
+		return false
+	}
+	// RECORDED, no longer derived. Until Phase B widens the candidate set the
+	// resolver still cannot mint a utility url, so this conjunct never fires
+	// and behaviour is byte-identical; it is what makes Phase B safe.
+	return !datahelpers.CTAMintedCovers(stored, field, url)
+}

